CREATE VIEW public.parts_consumption_authoritative WITH (security_invoker=on) AS
 SELECT id,
    organisation_id,
    country,
    event_date,
    txn_date,
    issue_number,
    work_order_no,
    asset_code,
    asset_description,
    asset_type,
    store_code,
    cost_center,
    item_code,
    qty,
    item_description,
    source_row,
    currency,
    site,
    region,
    branch,
    project,
    department,
    total_amount AS total_parts_consumption_raw,
    COALESCE(NULLIF(regexp_replace(total_amount, '[^0-9\.-]'::text, ''::text, 'g'::text), ''::text)::numeric, line_cost) AS total_parts_consumption
   FROM public.parts_consumption;
-- @@
CREATE VIEW public.parts_consumption_monthly_authoritative WITH (security_invoker=true) AS
 SELECT organisation_id,
    country,
    date_trunc('month'::text, COALESCE(event_date, to_date(NULLIF(txn_date, ''::text), 'YYYY-MM-DD'::text))::timestamp with time zone)::date AS month,
    sum(total_parts_consumption) AS total_parts_consumption
   FROM public.parts_consumption_authoritative
  WHERE COALESCE(event_date, to_date(NULLIF(txn_date, ''::text), 'YYYY-MM-DD'::text)) IS NOT NULL
  GROUP BY organisation_id, country, (date_trunc('month'::text, COALESCE(event_date, to_date(NULLIF(txn_date, ''::text), 'YYYY-MM-DD'::text))::timestamp with time zone)::date);
