CREATE VIEW public.v_asset_site_history WITH (security_invoker=on) AS
 WITH wo AS NOT MATERIALIZED (
         SELECT w.organisation_id,
            w.country,
            upper(btrim(w.asset_no::text)) AS asset_no,
            upper(btrim(w.site::text)) AS site,
            w.opened_at::date AS d
           FROM public.work_orders w
          WHERE NULLIF(btrim(w.asset_no::text), ''::text) IS NOT NULL AND NULLIF(btrim(w.site::text), ''::text) IS NOT NULL AND (upper(btrim(w.site::text)) <> ALL (ARRAY['KSA'::text, 'UAE'::text, 'EGYPT'::text, 'SAUDI ARABIA'::text])) AND w.opened_at >= '2000-01-01 00:00:00+00'::timestamp with time zone AND w.opened_at::date <= CURRENT_DATE
        ), m AS (
         SELECT wo.organisation_id,
            wo.country,
            wo.asset_no,
            date_trunc('month'::text, wo.d::timestamp with time zone)::date AS mon,
            wo.site,
            count(*) AS n,
            min(wo.d) AS first_d,
            max(wo.d) AS last_d
           FROM wo
          GROUP BY wo.organisation_id, wo.country, wo.asset_no, (date_trunc('month'::text, wo.d::timestamp with time zone)::date), wo.site
        ), mm AS (
         SELECT m.organisation_id,
            m.country,
            m.asset_no,
            m.mon,
            m.site,
            m.n,
            m.first_d,
            m.last_d,
            sum(m.n) OVER (PARTITION BY m.organisation_id, m.country, m.asset_no, m.mon) AS month_n,
            row_number() OVER (PARTITION BY m.organisation_id, m.country, m.asset_no, m.mon ORDER BY m.n DESC, m.last_d DESC, m.site) AS rk,
            lead(m.n) OVER (PARTITION BY m.organisation_id, m.country, m.asset_no, m.mon ORDER BY m.n DESC, m.last_d DESC, m.site) AS next_n
           FROM m
        ), top AS (
         SELECT mm.organisation_id,
            mm.country,
            mm.asset_no,
            mm.mon,
            mm.site,
            mm.n,
            mm.month_n,
            mm.first_d,
            mm.last_d,
            mm.n::numeric / mm.month_n AS share,
            mm.next_n IS NOT NULL AND mm.next_n = mm.n AS tie
           FROM mm
          WHERE mm.rk = 1
        ), grp AS (
         SELECT t.organisation_id,
            t.country,
            t.asset_no,
            t.mon,
            t.site,
            t.n,
            t.month_n,
            t.first_d,
            t.last_d,
            t.share,
            t.tie,
            t.prev_site,
            sum(
                CASE
                    WHEN t.site IS DISTINCT FROM t.prev_site THEN 1
                    ELSE 0
                END) OVER (PARTITION BY t.organisation_id, t.country, t.asset_no ORDER BY t.mon) AS run_no
           FROM ( SELECT top.organisation_id,
                    top.country,
                    top.asset_no,
                    top.mon,
                    top.site,
                    top.n,
                    top.month_n,
                    top.first_d,
                    top.last_d,
                    top.share,
                    top.tie,
                    lag(top.site) OVER (PARTITION BY top.organisation_id, top.country, top.asset_no ORDER BY top.mon) AS prev_site
                   FROM top) t
        ), runs AS (
         SELECT grp.organisation_id,
            grp.country,
            grp.asset_no,
            grp.run_no,
            min(grp.site) AS site,
            min(grp.first_d) AS valid_from,
            max(grp.last_d) AS last_evidence,
            count(*) AS months,
            sum(grp.n) AS job_cards,
            min(grp.share) AS min_share,
            bool_or(grp.tie) AS any_tie
           FROM grp
          GROUP BY grp.organisation_id, grp.country, grp.asset_no, grp.run_no
        ), runs2 AS NOT MATERIALIZED (
         SELECT r.organisation_id,
            r.country,
            r.asset_no,
            r.run_no,
            r.site,
            r.valid_from,
            r.last_evidence,
            r.months,
            r.job_cards,
            r.min_share,
            r.any_tie,
            lead(r.valid_from) OVER (PARTITION BY r.organisation_id, r.country, r.asset_no ORDER BY r.run_no) AS next_from,
            max(r.run_no) OVER (PARTITION BY r.organisation_id, r.country, r.asset_no) AS last_run,
            upper(btrim(f.site)) AS register_site
           FROM runs r
             LEFT JOIN public.vehicle_fleet f ON f.organisation_id = r.organisation_id AND f.country = r.country::text AND upper(btrim(f.asset_no)) = r.asset_no
        ), wo_periods AS (
         SELECT runs2.organisation_id,
            runs2.country,
            runs2.asset_no,
            runs2.site,
            runs2.valid_from,
                CASE
                    WHEN runs2.next_from IS NOT NULL THEN runs2.next_from - 1
                    WHEN runs2.register_site IS NOT NULL AND runs2.register_site IS DISTINCT FROM runs2.site THEN runs2.last_evidence
                    ELSE NULL::date
                END AS valid_to,
            'job_cards'::text AS evidence,
                CASE
                    WHEN runs2.job_cards >= 3::numeric AND runs2.months >= 2 AND runs2.min_share >= 0.8 AND NOT runs2.any_tie AND NOT (runs2.run_no = runs2.last_run AND runs2.register_site IS NOT NULL AND runs2.register_site IS DISTINCT FROM runs2.site) THEN 'confirmed'::text
                    ELSE 'provisional'::text
                END AS confidence,
            runs2.job_cards::integer AS job_cards,
            runs2.months::integer AS months,
            round(runs2.min_share, 2) AS min_month_share,
            runs2.last_evidence,
            runs2.register_site
           FROM runs2
        ), reg_after AS (
         SELECT runs2.organisation_id,
            runs2.country,
            runs2.asset_no,
            runs2.register_site AS site,
            runs2.last_evidence + 1 AS valid_from,
            NULL::date AS valid_to,
            'register_current'::text AS evidence,
            'provisional'::text AS confidence,
            0 AS "?column?",
            0 AS "?column?",
            NULL::numeric AS "numeric",
            NULL::date AS date,
            runs2.register_site
           FROM runs2
          WHERE runs2.run_no = runs2.last_run AND runs2.register_site IS NOT NULL AND runs2.register_site IS DISTINCT FROM runs2.site
        ), reg_only AS (
         SELECT f.organisation_id,
            f.country,
            upper(btrim(f.asset_no)) AS upper,
            upper(btrim(f.site)) AS upper,
            NULL::date AS date,
            NULL::date AS date,
            'register_current_only'::text AS text,
            'provisional'::text AS text,
            0 AS "?column?",
            0 AS "?column?",
            NULL::numeric AS "numeric",
            NULL::date AS date,
            upper(btrim(f.site)) AS upper
           FROM public.vehicle_fleet f
          WHERE NULLIF(btrim(f.site), ''::text) IS NOT NULL AND NULLIF(btrim(f.asset_no), ''::text) IS NOT NULL AND NOT (EXISTS ( SELECT 1
                   FROM wo
                  WHERE wo.organisation_id = f.organisation_id AND wo.country::text = f.country AND wo.asset_no = upper(btrim(f.asset_no))))
        )
 SELECT wo_periods.organisation_id,
    wo_periods.country,
    wo_periods.asset_no,
    wo_periods.site,
    wo_periods.valid_from,
    wo_periods.valid_to,
    wo_periods.evidence,
    wo_periods.confidence,
    wo_periods.job_cards,
    wo_periods.months,
    wo_periods.min_month_share,
    wo_periods.last_evidence,
    wo_periods.register_site
   FROM wo_periods
UNION ALL
 SELECT reg_after.organisation_id,
    reg_after.country,
    reg_after.asset_no,
    reg_after.site,
    reg_after.valid_from,
    reg_after.valid_to,
    reg_after.evidence,
    reg_after.confidence,
    reg_after."?column?" AS job_cards,
    reg_after."?column?_1" AS months,
    reg_after."numeric" AS min_month_share,
    reg_after.date AS last_evidence,
    reg_after.register_site
   FROM reg_after reg_after(organisation_id, country, asset_no, site, valid_from, valid_to, evidence, confidence, "?column?", "?column?_1", "numeric", date, register_site)
UNION ALL
 SELECT reg_only.organisation_id,
    reg_only.country,
    reg_only.upper AS asset_no,
    reg_only.upper_1 AS site,
    reg_only.date AS valid_from,
    reg_only.date_1 AS valid_to,
    reg_only.text AS evidence,
    reg_only.text_1 AS confidence,
    reg_only."?column?" AS job_cards,
    reg_only."?column?_1" AS months,
    reg_only."numeric" AS min_month_share,
    reg_only.date_2 AS last_evidence,
    reg_only.upper_2 AS register_site
   FROM reg_only reg_only(organisation_id, country, upper, upper_1, date, date_1, text, text_1, "?column?", "?column?_1", "numeric", date_2, upper_2);
-- @@
CREATE VIEW public.v_data_quality_issues WITH (security_invoker=on) AS
 SELECT id,
    issue_date,
    country,
    site,
    brand,
    serial_no,
    asset_no,
    cost_per_tyre,
    km_at_fitment,
    km_at_removal,
    category,
    risk_level,
    cleaned,
    brand IS NULL OR TRIM(BOTH FROM brand) = ''::text AS missing_brand,
    site IS NULL OR TRIM(BOTH FROM site) = ''::text AS missing_site,
    asset_no IS NULL OR TRIM(BOTH FROM asset_no) = ''::text AS missing_asset,
    serial_no IS NULL AS missing_serial,
    issue_date IS NULL AS missing_date,
    category IS NULL AS missing_category,
    risk_level IS NULL AS missing_risk,
    cost_per_tyre > 50000::numeric AS cost_too_high,
    cost_per_tyre < 100::numeric AS cost_too_low,
    km_at_removal < km_at_fitment AND km_at_fitment IS NOT NULL AND km_at_removal IS NOT NULL AS km_order_wrong,
    (
        CASE
            WHEN brand IS NULL OR brand = ''::text THEN 1
            ELSE 0
        END +
        CASE
            WHEN site IS NULL OR site = ''::text THEN 1
            ELSE 0
        END +
        CASE
            WHEN asset_no IS NULL THEN 1
            ELSE 0
        END +
        CASE
            WHEN issue_date IS NULL THEN 1
            ELSE 0
        END +
        CASE
            WHEN category IS NULL THEN 1
            ELSE 0
        END +
        CASE
            WHEN risk_level IS NULL THEN 1
            ELSE 0
        END +
        CASE
            WHEN cost_per_tyre > 50000::numeric OR cost_per_tyre < 100::numeric THEN 1
            ELSE 0
        END)::smallint AS issue_score
   FROM public.tyre_records t
  WHERE brand IS NULL OR TRIM(BOTH FROM brand) = ''::text OR site IS NULL OR TRIM(BOTH FROM site) = ''::text OR issue_date IS NULL OR category IS NULL OR risk_level IS NULL OR cost_per_tyre > 50000::numeric OR cost_per_tyre < 100::numeric OR km_at_removal < km_at_fitment AND km_at_fitment IS NOT NULL AND km_at_removal IS NOT NULL
  ORDER BY ((
        CASE
            WHEN brand IS NULL OR brand = ''::text THEN 1
            ELSE 0
        END +
        CASE
            WHEN site IS NULL OR site = ''::text THEN 1
            ELSE 0
        END +
        CASE
            WHEN asset_no IS NULL THEN 1
            ELSE 0
        END +
        CASE
            WHEN issue_date IS NULL THEN 1
            ELSE 0
        END +
        CASE
            WHEN category IS NULL THEN 1
            ELSE 0
        END +
        CASE
            WHEN risk_level IS NULL THEN 1
            ELSE 0
        END +
        CASE
            WHEN cost_per_tyre > 50000::numeric OR cost_per_tyre < 100::numeric THEN 1
            ELSE 0
        END)::smallint) DESC, created_at DESC;
-- @@
