CREATE VIEW public.v_jobcard_date_mismatch WITH (security_invoker=true) AS
 SELECT w.id,
    w.organisation_id,
    w.work_order_no,
    w.opened_at,
    w.country,
    w.site,
    p.mm AS jobcard_month,
    p.yy AS jobcard_year,
    date_part('month'::text, w.opened_at)::integer AS opened_month,
    date_part('year'::text, w.opened_at)::integer AS opened_year
   FROM public.work_orders w
     CROSS JOIN LATERAL public.jobcard_period(w.work_order_no::text) p(mm, yy)
  WHERE w.opened_at IS NOT NULL AND (p.mm <> date_part('month'::text, w.opened_at)::integer OR p.yy <> date_part('year'::text, w.opened_at)::integer);
-- @@
CREATE VIEW public.v_ksa_master_tyre_fitments WITH (security_invoker=on) AS
 WITH raw AS (
         SELECT COALESCE(public.master_clean_value(s.asset_no), public.master_clean_value(s."Asset No")) AS asset_no,
            public.master_clean_value(s.tire_pos) AS tyre_position,
            public.master_clean_value(s.srno) AS serial_no,
            public.master_clean_value(s.tire_size) AS size,
            public.master_clean_value(s.tyre_brand) AS brand,
            public.master_clean_value(s.old_serialno) AS old_serial_no,
            public.master_clean_value(s.old_tyrebrand) AS old_brand,
            public.master_clean_value(s."Asset Location") AS site,
            public.master_clean_value(s."Job Card No") AS job_card,
            to_date(public.master_clean_value(s.fix_date), 'DD-MM-YY'::text) AS fix_date,
            to_date(public.master_clean_value(s.remove_date), 'DD-MM-YY'::text) AS remove_date,
            public.master_clean_value(s."fix_KM")::numeric AS fix_km,
            public.master_clean_value(s."remove_KM")::numeric AS remove_km,
            public.master_clean_value(s."fix_HM")::numeric AS fix_hm,
            public.master_clean_value(s."remove_HM")::numeric AS remove_hm,
            public.master_clean_value(s.total_km)::numeric AS sheet_total_km
           FROM public.ksa_country_upload_template_staging s
          WHERE public.master_clean_value(s.srno) IS NOT NULL AND public.master_clean_value(s.tire_pos) IS NOT NULL
        ), grouped AS (
         SELECT raw.asset_no,
            raw.tyre_position,
            raw.serial_no,
            max(raw.size) AS size,
            max(raw.brand) AS brand,
            max(raw.old_serial_no) AS old_serial_no,
            max(raw.old_brand) AS old_brand,
            max(raw.site) AS site,
            min(raw.job_card) AS job_card,
            LEAST(min(raw.fix_date), min(raw.remove_date)) AS fit_date,
            GREATEST(max(raw.fix_date), max(raw.remove_date)) AS rem_date,
            LEAST(min(raw.fix_km), min(raw.remove_km)) AS fit_km,
            GREATEST(max(raw.fix_km), max(raw.remove_km)) AS rem_km,
            LEAST(min(raw.fix_hm), min(raw.remove_hm)) AS fit_hm,
            GREATEST(max(raw.fix_hm), max(raw.remove_hm)) AS rem_hm,
            max(raw.sheet_total_km) AS sheet_total_km,
            bool_or(raw.fix_date > raw.remove_date) AS date_was_reversed,
            bool_or(raw.fix_km > raw.remove_km) AS km_was_reversed,
            count(*) AS source_rows
           FROM raw
          GROUP BY raw.asset_no, raw.tyre_position, raw.serial_no
        ), typed AS (
         SELECT g.asset_no,
            g.tyre_position,
            g.serial_no,
            g.size,
            g.brand,
            g.old_serial_no,
            g.old_brand,
            g.site,
            g.job_card,
            g.fit_date,
            g.rem_date,
            g.fit_km,
            g.rem_km,
            g.fit_hm,
            g.rem_hm,
            g.sheet_total_km,
            g.date_was_reversed,
            g.km_was_reversed,
            g.source_rows,
            upper(btrim(COALESCE(f.vehicle_type, ''::text))) AS vehicle_type,
                CASE
                    WHEN g.rem_date IS DISTINCT FROM g.fit_date THEN g.rem_date
                    ELSE NULL::date
                END AS removal_date,
                CASE
                    WHEN g.rem_km IS DISTINCT FROM g.fit_km THEN g.rem_km
                    ELSE NULL::numeric
                END AS km_at_removal,
                CASE
                    WHEN g.rem_hm IS DISTINCT FROM g.fit_hm THEN g.rem_hm
                    ELSE NULL::numeric
                END AS hrs_at_removal
           FROM grouped g
             LEFT JOIN public.vehicle_fleet f ON f.country = 'KSA'::text AND upper(btrim(f.asset_no)) = g.asset_no
        ), measured AS (
         SELECT t.asset_no,
            t.tyre_position,
            t.serial_no,
            t.size,
            t.brand,
            t.old_serial_no,
            t.old_brand,
            t.site,
            t.job_card,
            t.fit_date,
            t.rem_date,
            t.fit_km,
            t.rem_km,
            t.fit_hm,
            t.rem_hm,
            t.sheet_total_km,
            t.date_was_reversed,
            t.km_was_reversed,
            t.source_rows,
            t.vehicle_type,
            t.removal_date,
            t.km_at_removal,
            t.hrs_at_removal,
                CASE
                    WHEN t.km_at_removal IS NOT NULL AND t.fit_km IS NOT NULL AND t.km_at_removal >= t.fit_km THEN t.km_at_removal - t.fit_km
                    ELSE t.sheet_total_km
                END AS total_km,
            t.km_at_removal IS NOT NULL AND t.fit_km IS NOT NULL AND t.km_at_removal >= t.fit_km AS km_recomputed
           FROM typed t
        )
 SELECT asset_no,
    tyre_position,
    serial_no,
    size,
    brand,
    old_serial_no,
    old_brand,
    site,
    job_card,
    vehicle_type,
    fit_date AS issue_date,
    removal_date,
    fit_km AS km_at_fitment,
    km_at_removal,
    fit_hm AS hrs_at_fitment,
    hrs_at_removal,
    total_km,
    sheet_total_km,
    km_recomputed,
    date_was_reversed,
    km_was_reversed,
    source_rows,
    public.tyre_life_km_cap(vehicle_type) AS life_cap_km,
    total_km IS NOT NULL AND total_km > public.tyre_life_km_cap(vehicle_type) AS life_over_cap,
    serial_no ~ 'E\+[0-9]+$'::text OR serial_no ~ '^(TIRE|TYRE)\M'::text OR length(serial_no) < 4 AS serial_suspect,
    (EXISTS ( SELECT 1
           FROM public.tyre_records t
          WHERE t.country = 'KSA'::text AND public.master_clean_token(t.asset_no) = m.asset_no AND public.master_clean_token(t.tyre_position) = m.tyre_position AND public.master_clean_token(t.serial_no) = m.serial_no)) AS already_loaded
   FROM measured m;
-- @@
CREATE VIEW public.v_stock_balance_reconcile WITH (security_invoker=true) AS
 SELECT s.id AS stock_id,
    s.site,
    s.description,
    s.organisation_id,
    s.stock_qty AS recorded_qty,
    COALESCE(l.ledger_qty, 0::bigint) AS ledger_qty,
    s.stock_qty - COALESCE(l.ledger_qty, 0::bigint) AS drift,
    s.stock_qty <> COALESCE(l.ledger_qty, 0::bigint) AS has_drift
   FROM public.stock_records s
     LEFT JOIN ( SELECT stock_movements.stock_id,
            sum(stock_movements.qty_change) AS ledger_qty
           FROM public.stock_movements
          GROUP BY stock_movements.stock_id) l ON l.stock_id = s.id;
-- @@
CREATE VIEW public.v_tyre_cost_status WITH (security_invoker=on) AS
 WITH priced_serials AS (
         SELECT tyre_records.country,
            upper(btrim(tyre_records.serial_no)) AS s,
            min(COALESCE(tyre_records.issue_date, tyre_records.fitment_date)) AS first_priced
           FROM public.tyre_records
          WHERE COALESCE(tyre_records.cost_per_tyre, 0::numeric) > 0::numeric AND public.tyre_serial_is_strong(tyre_records.serial_no)
          GROUP BY tyre_records.country, (upper(btrim(tyre_records.serial_no)))
        )
 SELECT t.id,
    t.country,
    t.asset_no,
    t.serial_no,
    t.issue_date,
    t.cost_per_tyre,
        CASE
            WHEN COALESCE(t.cost_per_tyre, 0::numeric) > 0::numeric AND bl.source = 'comparable'::text THEN 'estimated_comparable'::text
            WHEN COALESCE(t.cost_per_tyre, 0::numeric) > 0::numeric AND bl.source = 'own_jobcard'::text THEN 'from_job_card'::text
            WHEN COALESCE(t.cost_per_tyre, 0::numeric) > 0::numeric THEN 'purchase_price'::text
            WHEN cc.reason IS NOT NULL THEN 'cleared_'::text || cc.reason
            WHEN public.tyre_serial_is_strong(t.serial_no) AND ps.s IS NOT NULL THEN 'refit_no_new_purchase'::text
            ELSE 'unpriced'::text
        END AS cost_status
   FROM public.tyre_records t
     LEFT JOIN LATERAL ( SELECT l.source
           FROM public.tyre_price_backfill_log l
          WHERE l.tyre_id = t.id AND NOT l.new_cost IS DISTINCT FROM t.cost_per_tyre
          ORDER BY l.created_at DESC
         LIMIT 1) bl ON true
     LEFT JOIN LATERAL ( SELECT c.reason
           FROM public.tyre_cost_corrections c
          WHERE c.tyre_id = t.id AND c.undone_at IS NULL AND NOT c.new_cost IS DISTINCT FROM t.cost_per_tyre
          ORDER BY c.created_at DESC
         LIMIT 1) cc ON true
     LEFT JOIN priced_serials ps ON NOT ps.country IS DISTINCT FROM t.country AND ps.s = upper(btrim(t.serial_no));
-- @@
CREATE VIEW public.v_tyre_life_over_cap WITH (security_invoker=on) AS
 SELECT id,
    country,
    asset_no,
    tyre_position,
    serial_no,
    brand,
    size,
    COALESCE(NULLIF(btrim(vehicle_type), ''::text), '(no type recorded)'::text) AS vehicle_type,
    issue_date,
    removal_date,
    km_at_fitment,
    km_at_removal,
    total_km,
    public.tyre_life_km_cap(vehicle_type) AS life_cap_km,
    total_km - public.tyre_life_km_cap(vehicle_type) AS over_by_km,
        CASE
            WHEN km_at_fitment IS NULL OR km_at_removal IS NULL THEN 'meters missing'::text
            WHEN (km_at_removal - km_at_fitment) <= public.tyre_life_km_cap(vehicle_type) THEN 'recomputable from meters'::text
            WHEN COALESCE(km_at_fitment, 0::numeric) <= 1::numeric THEN 'fitment km looks like a placeholder'::text
            ELSE 'meters agree - needs a person'::text
        END AS likely_cause
   FROM public.tyre_records t
  WHERE total_km IS NOT NULL AND total_km > public.tyre_life_km_cap(vehicle_type);
-- @@
CREATE VIEW public.v_tyre_lifetime_fitments WITH (security_invoker=on) AS
 WITH f AS (
         SELECT t.id,
            t.organisation_id,
            t.country,
            t.asset_no,
            t.site,
            t.brand,
            t.size,
            t.vehicle_type,
            COALESCE(t.tyre_position, t."position") AS "position",
            t.serial_no,
            t.status,
            t.qty,
            COALESCE(t.issue_date, t.fitment_date) AS fit_date,
            t.removal_date,
            t.km_at_fitment,
            t.km_at_removal,
            t.total_km,
            t.cost_per_tyre,
            public.tyre_serial_is_strong(t.serial_no) AS strong,
                CASE
                    WHEN public.tyre_serial_is_strong(t.serial_no) THEN (upper(btrim(COALESCE(t.country, ''::text))) || '|'::text) || upper(btrim(t.serial_no))
                    ELSE 'row:'::text || t.id::text
                END AS tyre_key,
            public.tyre_km_life(t.km_at_fitment, t.km_at_removal, t.total_km, t.vehicle_type) AS km,
            t.removal_date IS NOT NULL OR t.km_at_removal IS NOT NULL AS completed,
            public.tyre_status_is_active(t.status) AS active
           FROM public.tyre_records t
        ), o AS (
         SELECT f.id,
            f.organisation_id,
            f.country,
            f.asset_no,
            f.site,
            f.brand,
            f.size,
            f.vehicle_type,
            f."position",
            f.serial_no,
            f.status,
            f.qty,
            f.fit_date,
            f.removal_date,
            f.km_at_fitment,
            f.km_at_removal,
            f.total_km,
            f.cost_per_tyre,
            f.strong,
            f.tyre_key,
            f.km,
            f.completed,
            f.active,
            row_number() OVER w AS fit_seq,
            max(
                CASE
                    WHEN f.removal_date IS NOT NULL THEN f.removal_date
                    WHEN NOT f.completed AND f.active THEN 'infinity'::date
                    ELSE NULL::date
                END) OVER (w ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING) AS prev_end
           FROM f
          WINDOW w AS (PARTITION BY f.tyre_key ORDER BY f.fit_date NULLS FIRST, f.id)
        )
 SELECT id,
    organisation_id,
    country,
    asset_no,
    site,
    brand,
    size,
    vehicle_type,
    "position",
    serial_no,
    status,
    qty,
    fit_date,
    removal_date,
    km_at_fitment,
    km_at_removal,
    total_km,
    cost_per_tyre,
    strong,
    tyre_key,
    km,
    completed,
    active,
    fit_seq,
    prev_end,
    fit_date IS NOT NULL AND prev_end IS NOT NULL AND fit_date < prev_end AS is_overlap
   FROM o;
-- @@
CREATE VIEW public.v_tyre_master WITH (security_invoker=on) AS
 SELECT id,
    sr,
    issue_date,
    country,
    public.normalize_site(site) AS site,
    public.normalize_brand(brand) AS brand,
    serial_no,
    asset_no,
