    job_card,
    description,
    COALESCE(remarks_cleaned, remarks) AS remarks,
    category,
    risk_level,
    qty,
    cost_per_tyre,
    cost_per_tyre * COALESCE(qty, 1)::numeric AS total_cost,
    km_at_fitment,
    km_at_removal,
    public.calc_cpk(cost_per_tyre, km_at_fitment, km_at_removal) AS cpk,
        CASE
            WHEN issue_date IS NOT NULL THEN CURRENT_DATE - issue_date
            ELSE NULL::integer
        END AS age_days,
    cleaned,
    data_source,
    upload_batch_id,
    created_at,
    uploaded_by
   FROM public.tyre_records t;
