CREATE VIEW public.workforce_assignment_durations WITH (security_invoker=on) AS
 WITH seq AS (
         SELECT e.assignment_id,
            e.action,
            e.to_status,
            e.effective_at,
            lead(e.effective_at) OVER w AS next_at,
            max(e.effective_at) FILTER (WHERE e.action = 'complete'::text) OVER (PARTITION BY e.assignment_id) AS completed_at
           FROM public.workforce_assignment_events e
          WINDOW w AS (PARTITION BY e.assignment_id ORDER BY e.effective_at, e.occurred_at, e.id)
        ), spans AS (
         SELECT seq.assignment_id,
            seq.completed_at,
            sum(EXTRACT(epoch FROM seq.next_at - seq.effective_at) / 60.0) FILTER (WHERE seq.to_status = 'in_progress'::text AND seq.next_at IS NOT NULL AND seq.effective_at < seq.completed_at) AS active_minutes
           FROM seq
          GROUP BY seq.assignment_id, seq.completed_at
        )
 SELECT a.id AS assignment_id,
    a.organisation_id,
    a.task_type,
    a.vehicle_type,
    a.assignee_role,
    round(s.active_minutes, 1) AS active_minutes,
    s.completed_at
   FROM spans s
     JOIN public.workforce_assignments a ON a.id = s.assignment_id
  WHERE s.completed_at IS NOT NULL AND s.active_minutes IS NOT NULL AND (a.status = ANY (ARRAY['submitted'::text, 'verified'::text]));
-- @@
CREATE VIEW public.v_tyre_lifecycle_events WITH (security_invoker=on) AS
 WITH fl AS (
         SELECT f.id,
            f.organisation_id,
            f.country,
            f.asset_no,
            f.site,
            f.brand,
            f.size,
            f.vehicle_type,
            f."position",
            f.serial_no,
            f.status,
            f.qty,
            f.fit_date,
            f.removal_date,
            f.km_at_fitment,
            f.km_at_removal,
            f.total_km,
            f.cost_per_tyre,
            f.strong,
            f.tyre_key,
            f.km,
            f.completed,
            f.active,
            f.fit_seq,
            f.prev_end,
            f.is_overlap,
            lag(f.asset_no) OVER w AS prev_asset_no,
            lag(f."position") OVER w AS prev_position,
            lag(f.fit_date) OVER w AS prev_fit_date,
            lag(f.removal_date) OVER w AS prev_removal_date,
            lag(f.completed) OVER w AS prev_completed,
            lag(f.active) OVER w AS prev_active,
            lead(f.fit_date) OVER w AS next_fit_date,
            lead(f.id) OVER w AS next_id,
            first_value(f.id) OVER (PARTITION BY f.tyre_key ORDER BY (COALESCE(f.cost_per_tyre, 0::numeric) > 0::numeric) DESC, f.fit_seq) AS first_priced_id,
            bool_or(COALESCE(f.cost_per_tyre, 0::numeric) > 0::numeric) OVER (PARTITION BY f.tyre_key) AS tyre_priced
           FROM public.v_tyre_lifetime_fitments f
          WINDOW w AS (PARTITION BY f.tyre_key ORDER BY f.fit_date NULLS FIRST, f.id)
        ), fit_ev AS (
         SELECT fl.id,
            fl.organisation_id,
            fl.country,
            fl.asset_no,
            fl.site,
            fl.brand,
            fl.size,
            fl.vehicle_type,
            fl."position",
            fl.serial_no,
            fl.status,
            fl.qty,
            fl.fit_date,
            fl.removal_date,
            fl.km_at_fitment,
            fl.km_at_removal,
            fl.total_km,
            fl.cost_per_tyre,
            fl.strong,
            fl.tyre_key,
            fl.km,
            fl.completed,
            fl.active,
            fl.fit_seq,
            fl.prev_end,
            fl.is_overlap,
            fl.prev_asset_no,
            fl.prev_position,
            fl.prev_fit_date,
            fl.prev_removal_date,
            fl.prev_completed,
            fl.prev_active,
            fl.next_fit_date,
            fl.next_id,
            fl.first_priced_id,
            fl.tyre_priced,
                CASE
                    WHEN fl.fit_seq = 1 THEN NULL::text
                    WHEN fl.fit_date IS NOT NULL AND fl.fit_date = fl.prev_fit_date THEN 'same_day_double_entry'::text
                    WHEN fl.is_overlap AND fl.prev_end = 'infinity'::date THEN 'earlier_fitment_still_open'::text
                    WHEN fl.is_overlap THEN 'overlaps_earlier_fitment'::text
                    WHEN fl.fit_date IS NULL THEN 'no_fitment_date'::text
                    WHEN NULLIF(btrim(COALESCE(fl.asset_no, ''::text)), ''::text) IS NULL OR NULLIF(btrim(COALESCE(fl.prev_asset_no, ''::text)), ''::text) IS NULL THEN 'vehicle_not_recorded'::text
                    WHEN upper(btrim(fl.asset_no)) = upper(btrim(fl.prev_asset_no)) AND (NULLIF(btrim(COALESCE(fl."position", ''::text)), ''::text) IS NULL OR NULLIF(btrim(COALESCE(fl.prev_position, ''::text)), ''::text) IS NULL) THEN 'position_not_recorded'::text
                    ELSE NULL::text
                END AS amb
           FROM fl
        ), ev AS (
         SELECT e.tyre_key,
            e.organisation_id,
            e.country,
            e.serial_no,
            e.fit_date AS event_date,
            e.fit_seq * 10 AS ord,
                CASE
                    WHEN e.fit_seq = 1 THEN 'FIT'::text
                    WHEN e.amb IS NOT NULL THEN 'AMBIGUOUS'::text
                    WHEN upper(btrim(e.asset_no)) <> upper(btrim(e.prev_asset_no)) THEN 'TRANSFER'::text
                    WHEN upper(btrim(e."position")) = upper(btrim(e.prev_position)) THEN 'REFIT_SAME_VEHICLE'::text
                    ELSE 'ROTATION'::text
                END AS event_type,
            e.amb AS ambiguous_reason,
            e.asset_no,
            e."position",
                CASE
                    WHEN e.fit_seq > 1 THEN e.prev_asset_no
                    ELSE NULL::text
                END AS from_asset_no,
                CASE
                    WHEN e.fit_seq > 1 THEN e.prev_position
                    ELSE NULL::text
                END AS from_position,
            e.km_at_fitment AS odometer_km,
            NULL::numeric AS km,
            e.fit_seq = 1 AND e.tyre_priced AS is_purchase,
            e.id AS fitment_id,
            'tyre_records'::text AS source_table,
            e.id::text AS source_id,
                CASE
                    WHEN e.fit_seq = 1 AND e.tyre_priced AND e.id <> e.first_priced_id THEN ('purchase price is recorded on a later fitment row ('::text || e.first_priced_id) || ')'::text
                    WHEN e.fit_seq > 1 AND e.prev_removal_date IS NULL AND NOT e.prev_completed AND NOT e.prev_active THEN 'previous fitment has no removal date'::text
                    ELSE NULL::text
                END AS detail
           FROM fit_ev e
        UNION ALL
         SELECT fl.tyre_key,
            fl.organisation_id,
            fl.country,
            fl.serial_no,
            fl.removal_date,
            fl.fit_seq * 10 + 1,
            'REMOVAL'::text,
            NULL::text,
            fl.asset_no,
            fl."position",
            NULL::text,
            NULL::text,
            fl.km_at_removal,
                CASE
                    WHEN fl.km > 0::numeric THEN fl.km
                    ELSE NULL::numeric
                END AS "case",
            false,
            fl.id,
            'tyre_records'::text,
            fl.id::text AS id,
            concat_ws('; '::text,
                CASE
                    WHEN fl.is_overlap THEN 'km not counted in life: overlaps an earlier fitment'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN rl.id IS NOT NULL THEN ((('closed by system reconcile ('::text || rl.source) || ', log '::text) || rl.id) || ')'::text
                    ELSE NULL::text
                END) AS concat_ws
           FROM fl
             LEFT JOIN LATERAL ( SELECT l.id,
                    l.source
                   FROM public.tyre_replacement_log l
                  WHERE l.tyre_id = fl.id AND l.undone_at IS NULL
                  ORDER BY l.id DESC
                 LIMIT 1) rl ON true
          WHERE fl.completed
        UNION ALL
         SELECT fl.tyre_key,
            fl.organisation_id,
            fl.country,
            fl.serial_no,
            fl.removal_date,
            fl.fit_seq * 10 + 2,
            'RETURN_TO_STORE'::text,
            NULL::text,
            NULL::text,
            NULL::text,
            fl.asset_no,
            fl."position",
            NULL::numeric,
            NULL::numeric,
            false,
            fl.id,
            'tyre_records'::text,
            fl.id::text AS id,
            ('inferred: off a vehicle '::text || (fl.next_fit_date - fl.removal_date)) || ' day(s) before refit'::text
           FROM fl
          WHERE fl.removal_date IS NOT NULL AND fl.next_fit_date IS NOT NULL AND fl.next_fit_date > fl.removal_date
        UNION ALL
         SELECT (upper(btrim(COALESCE(m.country, ''::text))) || '|'::text) || upper(btrim(m.serial)),
            m.organisation_id,
            m.country,
            m.serial,
            m.created_at::date AS created_at,
            1000000,
            'SCRAP'::text,
            NULL::text,
            NULL::text,
            NULL::text,
            NULL::text,
            NULL::text,
            NULL::numeric,
            NULL::numeric,
            false,
            NULL::uuid,
            'tyre_status_marks'::text,
            m.id::text AS id,
            NULLIF(btrim(COALESCE(m.reason, ''::text)), ''::text) AS "nullif"
           FROM public.tyre_status_marks m
          WHERE m.mark_type = 'scrap'::text AND public.tyre_serial_is_strong(m.serial)
        UNION ALL
         SELECT fl.tyre_key,
            fl.organisation_id,
            fl.country,
            fl.serial_no,
            fl.removal_date,
            fl.fit_seq * 10 + 3,
            'SCRAP'::text,
            NULL::text,
            fl.asset_no,
            fl."position",
            NULL::text,
            NULL::text,
            NULL::numeric,
            NULL::numeric,
            false,
            fl.id,
            'tyre_records'::text,
            fl.id::text AS id,
            'status Scrapped, no scrap mark'::text
           FROM fl
          WHERE fl.status ~~* '%scrap%'::text AND NOT (EXISTS ( SELECT 1
                   FROM public.tyre_status_marks m
                  WHERE m.mark_type = 'scrap'::text AND public.tyre_serial_is_strong(m.serial) AND ((upper(btrim(COALESCE(m.country, ''::text))) || '|'::text) || upper(btrim(m.serial))) = fl.tyre_key))
        UNION ALL
         SELECT COALESCE(
                CASE
                    WHEN public.tyre_serial_is_strong(j.casing_serial) THEN (upper(btrim(COALESCE(j.country, ''::text))) || '|'::text) || upper(btrim(j.casing_serial))
                    ELSE NULL::text
                END, fr.tyre_key) AS "coalesce",
            j.organisation_id,
            j.country,
            COALESCE(j.casing_serial, fr.serial_no) AS "coalesce",
            COALESCE(j.returned_at, j.sent_at) AS "coalesce",
            2000000,
            'RETREAD'::text,
            NULL::text,
            j.last_asset_no,
            NULL::text,
            NULL::text,
            NULL::text,
            NULL::numeric,
            NULL::numeric,
            false,
            j.tyre_record_id,
            'retread_jobs'::text,
            j.id::text AS id,
            concat_ws(', '::text, j.vendor_name, j.status) AS concat_ws
           FROM public.retread_jobs j
             LEFT JOIN fl fr ON fr.id = j.tyre_record_id
          WHERE COALESCE(j.returned_at, j.sent_at) IS NOT NULL AND (public.tyre_serial_is_strong(j.casing_serial) OR fr.tyre_key IS NOT NULL)
        UNION ALL
         SELECT (upper(btrim(COALESCE(s.country, ''::text))) || '|'::text) || upper(btrim(s.tyre_serial)),
            s.organisation_id,
            s.country,
            s.tyre_serial,
            s.event_date,
                CASE
                    WHEN s.event_type ~~* '%retread%'::text THEN 2000000
                    ELSE 1500000
                END AS "case",
                CASE
                    WHEN s.event_type ~~* '%retread%'::text THEN 'RETREAD'::text
                    ELSE 'ROTATION'::text
                END AS "case",
            NULL::text,
            s.asset_no,
            s."position",
            NULL::text,
            NULL::text,
            s.odometer_km,
            NULL::numeric,
            false,
            NULL::uuid,
            'tyre_service_events'::text,
            s.id::text AS id,
            NULLIF(btrim(COALESCE(s.notes, ''::text)), ''::text) AS "nullif"
           FROM public.tyre_service_events s
          WHERE public.tyre_serial_is_strong(s.tyre_serial) AND (s.event_type ~~* '%retread%'::text OR s.event_type ~~* '%rotat%'::text)
        UNION ALL
         SELECT (upper(btrim(COALESCE(w.country, ''::text))) || '|'::text) || upper(btrim(w.serial_number)),
            w.organisation_id,
            w.country,
            w.serial_number,
            COALESCE(w.decision_date, w.credit_date, w.removal_date) AS "coalesce",
            3000000,
            'WARRANTY_REPLACEMENT'::text,
            NULL::text,
            w.asset_no,
            NULL::text,
            NULL::text,
            NULL::text,
            w.km_at_removal,
            w.km_run,
            false,
            NULL::uuid,
            'warranty_claims'::text,
            w.id::text AS id,
            concat_ws(', '::text, w.claim_no, w.claim_status) AS concat_ws
           FROM public.warranty_claims w
          WHERE public.tyre_serial_is_strong(w.serial_number) AND (w.claim_status = ANY (ARRAY['Approved'::text, 'Credit Issued'::text, 'Closed'::text])) AND w.rejection_reason IS NULL
        UNION ALL
         SELECT fr.tyre_key,
            d.organisation_id,
            fr.country,
            fr.serial_no,
            d.disposed_on,
            4000000,
            'DISPOSAL'::text,
            NULL::text,
            NULL::text,
            NULL::text,
            NULL::text,
            NULL::text,
            NULL::numeric,
            NULL::numeric,
            false,
            d.tyre_record_id,
            'tyre_disposals'::text,
            d.tyre_record_id::text AS tyre_record_id,
            concat_ws(', '::text, d.disposal_method, d.disposal_vendor) AS concat_ws
           FROM public.tyre_disposals d
             JOIN fl fr ON fr.id = d.tyre_record_id
          WHERE d.disposed_on IS NOT NULL
        )
 SELECT tyre_key,
    organisation_id,
    country,
    serial_no,
    row_number() OVER (PARTITION BY tyre_key ORDER BY event_date NULLS FIRST, ord, source_table, source_id) AS event_seq,
    event_date,
    event_type,
    ambiguous_reason,
    asset_no,
    "position",
    from_asset_no,
    from_position,
    odometer_km,
    km,
    is_purchase,
    fitment_id,
    source_table,
    source_id,
    NULLIF(detail, ''::text) AS detail
   FROM ev;
-- @@
CREATE VIEW public.v_tyre_lifetime WITH (security_invoker=on) AS
 WITH fl AS (
         SELECT v_tyre_lifetime_fitments.id,
            v_tyre_lifetime_fitments.organisation_id,
            v_tyre_lifetime_fitments.country,
            v_tyre_lifetime_fitments.asset_no,
            v_tyre_lifetime_fitments.site,
            v_tyre_lifetime_fitments.brand,
            v_tyre_lifetime_fitments.size,
            v_tyre_lifetime_fitments.vehicle_type,
            v_tyre_lifetime_fitments."position",
            v_tyre_lifetime_fitments.serial_no,
            v_tyre_lifetime_fitments.status,
            v_tyre_lifetime_fitments.qty,
            v_tyre_lifetime_fitments.fit_date,
            v_tyre_lifetime_fitments.removal_date,
            v_tyre_lifetime_fitments.km_at_fitment,
            v_tyre_lifetime_fitments.km_at_removal,
            v_tyre_lifetime_fitments.total_km,
            v_tyre_lifetime_fitments.cost_per_tyre,
            v_tyre_lifetime_fitments.strong,
            v_tyre_lifetime_fitments.tyre_key,
            v_tyre_lifetime_fitments.km,
            v_tyre_lifetime_fitments.completed,
            v_tyre_lifetime_fitments.active,
            v_tyre_lifetime_fitments.fit_seq,
            v_tyre_lifetime_fitments.prev_end,
            v_tyre_lifetime_fitments.is_overlap
           FROM public.v_tyre_lifetime_fitments
        ), dup_price AS (
         SELECT fl.tyre_key
           FROM fl
          WHERE fl.strong AND COALESCE(fl.cost_per_tyre, 0::numeric) > 0::numeric
          GROUP BY fl.tyre_key
         HAVING count(*) > 1
        ), bl AS (
         SELECT DISTINCT ON (l.tyre_id, l.new_cost) l.tyre_id,
            l.new_cost,
            l.source
           FROM public.tyre_price_backfill_log l
          ORDER BY l.tyre_id, l.new_cost, l.created_at DESC
        ), pv AS (
         SELECT tyre_price_provenance.tyre_id,
            tyre_price_provenance.source
           FROM public.tyre_price_provenance
        ), wz AS (
         SELECT DISTINCT fl.tyre_key
           FROM public.tyre_price_backfill_log l
             JOIN fl ON fl.id = l.tyre_id
          WHERE l.source = 'warranty'::text AND COALESCE(l.new_cost, 0::numeric) = 0::numeric
        ), svc AS (
         SELECT (upper(btrim(COALESCE(tyre_service_events.country, ''::text))) || '|'::text) || upper(btrim(tyre_service_events.tyre_serial)) AS tyre_key,
            sum(tyre_service_events.cost) FILTER (WHERE tyre_service_events.event_type ~~* '%repair%'::text) AS repair,
            sum(tyre_service_events.cost) FILTER (WHERE tyre_service_events.event_type ~~* '%retread%'::text) AS retread
           FROM public.tyre_service_events
          WHERE COALESCE(tyre_service_events.cost, 0::numeric) > 0::numeric AND public.tyre_serial_is_strong(tyre_service_events.tyre_serial)
          GROUP BY ((upper(btrim(COALESCE(tyre_service_events.country, ''::text))) || '|'::text) || upper(btrim(tyre_service_events.tyre_serial)))
        ), rj AS (
         SELECT COALESCE(
                CASE
                    WHEN public.tyre_serial_is_strong(j.casing_serial) THEN (upper(btrim(COALESCE(j.country, ''::text))) || '|'::text) || upper(btrim(j.casing_serial))
                    ELSE NULL::text
                END, fr.tyre_key) AS tyre_key,
            sum(j.cost) AS retread
           FROM public.retread_jobs j
             LEFT JOIN fl fr ON fr.id = j.tyre_record_id
          WHERE COALESCE(j.cost, 0::numeric) > 0::numeric AND j.returned_at IS NOT NULL
          GROUP BY (COALESCE(
                CASE
                    WHEN public.tyre_serial_is_strong(j.casing_serial) THEN (upper(btrim(COALESCE(j.country, ''::text))) || '|'::text) || upper(btrim(j.casing_serial))
                    ELSE NULL::text
                END, fr.tyre_key))
        ), wc AS (
         SELECT (upper(btrim(COALESCE(warranty_claims.country, ''::text))) || '|'::text) || upper(btrim(warranty_claims.serial_number)) AS tyre_key,
            sum(warranty_claims.credit_amount) AS recovery
           FROM public.warranty_claims
          WHERE COALESCE(warranty_claims.credit_amount, 0::numeric) > 0::numeric AND warranty_claims.credit_date IS NOT NULL AND (warranty_claims.claim_status = ANY (ARRAY['Credit Issued'::text, 'Closed'::text])) AND public.tyre_serial_is_strong(warranty_claims.serial_number)
          GROUP BY ((upper(btrim(COALESCE(warranty_claims.country, ''::text))) || '|'::text) || upper(btrim(warranty_claims.serial_number)))
        ), agg AS (
         SELECT fl.tyre_key,
            bool_or(fl.strong) AS strong,
            min(fl.country) AS country,
            min(fl.organisation_id::text)::uuid AS organisation_id,
            count(*) AS fitments,
            count(DISTINCT upper(btrim(fl.asset_no))) FILTER (WHERE fl.asset_no IS NOT NULL) AS vehicles,
            min(fl.fit_date) AS first_fit_date,
            max(fl.fit_date) AS last_fit_date,
            max(fl.removal_date) AS last_removal_date,
            bool_or(fl.active) AS is_active,
            (array_agg(fl.id ORDER BY fl.fit_seq DESC))[1] AS latest_id,
            (array_agg(fl.asset_no ORDER BY fl.fit_seq DESC))[1] AS asset_no,
            (array_agg(fl.site ORDER BY fl.fit_seq DESC))[1] AS site,
            (array_agg(fl.brand ORDER BY fl.fit_seq DESC))[1] AS brand,
            (array_agg(fl.size ORDER BY fl.fit_seq DESC))[1] AS size,
            (array_agg(fl.vehicle_type ORDER BY fl.fit_seq DESC))[1] AS vehicle_type,
            (array_agg(fl.serial_no ORDER BY fl.fit_seq DESC))[1] AS serial_no,
            (array_agg(fl.status ORDER BY fl.fit_seq DESC))[1] AS status,
            (array_agg(fl.qty ORDER BY fl.fit_seq DESC))[1] AS last_qty,
            (array_agg(fl.id ORDER BY fl.fit_seq) FILTER (WHERE COALESCE(fl.cost_per_tyre, 0::numeric) > 0::numeric))[1] AS priced_id,
            (array_agg(fl.cost_per_tyre ORDER BY fl.fit_seq) FILTER (WHERE COALESCE(fl.cost_per_tyre, 0::numeric) > 0::numeric))[1] AS purchase_cost,
            sum(fl.km) FILTER (WHERE fl.km > 0::numeric AND NOT fl.is_overlap) AS km_known,
            count(*) FILTER (WHERE fl.completed AND COALESCE(fl.km, 0::numeric) <= 0::numeric) AS km_unknown_fitments,
            count(*) FILTER (WHERE fl.is_overlap) AS overlapping_fitments
           FROM fl
          GROUP BY fl.tyre_key
        )
 SELECT a.tyre_key,
    a.strong,
    a.organisation_id,
    a.country,
    a.serial_no,
    a.latest_id,
    a.priced_id,
    a.asset_no,
    a.site,
    a.brand,
    a.size,
    a.vehicle_type,
    a.status,
    a.is_active,
    a.fitments,
    a.vehicles,
    a.first_fit_date,
    a.last_fit_date,
    a.last_removal_date,
        CASE
            WHEN a.strong THEN 1
            ELSE GREATEST(1, COALESCE(a.last_qty, 1))
        END AS qty,
    a.km_known,
    a.km_unknown_fitments,
    a.overlapping_fitments,
        CASE
            WHEN a.km_known IS NULL THEN 'none'::text
            WHEN a.km_unknown_fitments > 0 OR a.overlapping_fitments > 0 THEN 'partial'::text
            ELSE 'complete'::text
        END AS km_coverage,
    a.purchase_cost,
        CASE
            WHEN dp.tyre_key IS NOT NULL THEN 'DISPUTED'::text
            WHEN a.purchase_cost > 0::numeric AND (bl.source = 'comparable'::text OR pv.source = 'comparable'::text) THEN 'ESTIMATED'::text
            WHEN a.purchase_cost > 0::numeric THEN 'ACTUAL'::text
            WHEN wz.tyre_key IS NOT NULL THEN 'CONFIRMED_ZERO'::text
            ELSE 'MISSING'::text
        END AS purchase_cost_status,
    COALESCE(s.repair, 0::numeric) AS repair_cost,
    COALESCE(r.retread, s.retread, 0::numeric) AS retread_cost,
    COALESCE(w.recovery, 0::numeric) AS recovery,
        CASE
            WHEN a.purchase_cost > 0::numeric THEN a.purchase_cost + COALESCE(s.repair, 0::numeric) + COALESCE(r.retread, s.retread, 0::numeric) - COALESCE(w.recovery, 0::numeric)
            ELSE NULL::numeric
        END AS full_cost,
    a.is_active OR a.km_known IS NULL OR a.km_unknown_fitments > 0 OR a.overlapping_fitments > 0 AS provisional
   FROM agg a
     LEFT JOIN dup_price dp ON dp.tyre_key = a.tyre_key
     LEFT JOIN svc s ON s.tyre_key = a.tyre_key
     LEFT JOIN rj r ON r.tyre_key = a.tyre_key
     LEFT JOIN wc w ON w.tyre_key = a.tyre_key
     LEFT JOIN bl ON bl.tyre_id = a.priced_id AND bl.new_cost = a.purchase_cost
     LEFT JOIN pv ON pv.tyre_id = a.priced_id
     LEFT JOIN wz ON wz.tyre_key = a.tyre_key;
-- @@
CREATE VIEW public.v_tyre_fitment_evidence WITH (security_invoker=on) AS
 WITH wo AS (
         SELECT DISTINCT upper(btrim(work_orders.work_order_no::text)) AS n
           FROM public.work_orders
          WHERE work_orders.work_order_no IS NOT NULL AND btrim(work_orders.work_order_no::text) <> ''::text
        ), f AS (
         SELECT v.id,
            v.organisation_id,
            v.country,
            v.asset_no,
            v.site,
            v.brand,
            v.size,
            v.vehicle_type,
            v."position",
            v.serial_no,
            v.status,
            v.qty,
            v.fit_date,
            v.removal_date,
            v.km_at_fitment,
            v.km_at_removal,
            v.total_km,
            v.cost_per_tyre,
            v.strong,
            v.tyre_key,
            v.km,
            v.completed,
            v.active,
            v.fit_seq,
            v.is_overlap,
            t.job_card,
            t.created_at,
            public.tyre_life_km_cap(v.vehicle_type) AS km_cap,
            lt.purchase_cost_status
           FROM public.v_tyre_lifetime_fitments v
             JOIN public.tyre_records t ON t.id = v.id
             LEFT JOIN public.v_tyre_lifetime lt ON lt.tyre_key = v.tyre_key
        ), g AS (
         SELECT f.id,
            f.organisation_id,
            f.country,
            f.asset_no,
            f.site,
            f.brand,
            f.size,
            f.vehicle_type,
            f."position",
            f.serial_no,
            f.status,
            f.qty,
            f.fit_date,
            f.removal_date,
            f.km_at_fitment,
            f.km_at_removal,
            f.total_km,
            f.cost_per_tyre,
            f.strong,
            f.tyre_key,
            f.km,
            f.completed,
            f.active,
            f.fit_seq,
            f.is_overlap,
            f.job_card,
            f.created_at,
            f.km_cap,
            f.purchase_cost_status,
                CASE
                    WHEN f.fit_date IS NULL THEN 'undated'::text
                    WHEN f.fit_date < '2025-01-01'::date THEN 'legacy'::text
                    ELSE 'modern'::text
                END AS era,
            row_number() OVER (PARTITION BY f.country, (upper(btrim(COALESCE(f.asset_no, ''::text)))), (upper(btrim(COALESCE(f."position", ''::text)))), (upper(btrim(COALESCE(f.serial_no, ''::text)))), f.fit_date, f.km_at_fitment, f.km_at_removal, f.removal_date ORDER BY f.created_at, f.id) > 1 AS is_duplicate,
            f.active AND count(*) FILTER (WHERE f.active) OVER (PARTITION BY f.country, (upper(btrim(COALESCE(f.asset_no, ''::text)))), (upper(btrim(COALESCE(f."position", ''::text))))) > 1 AND COALESCE(btrim(f."position"), ''::text) <> ''::text AS double_active_wheel,
            f.strong AND f.active AND min(upper(btrim(f.asset_no))) FILTER (WHERE f.active) OVER (PARTITION BY f.tyre_key) <> max(upper(btrim(f.asset_no))) FILTER (WHERE f.active) OVER (PARTITION BY f.tyre_key) AS serial_active_two_vehicles,
            (EXISTS ( SELECT 1
                   FROM wo
                  WHERE wo.n = upper(btrim(f.job_card)))) AS job_card_found,
            f.removal_date IS NOT NULL AND f.fit_date IS NOT NULL AND f.removal_date < f.fit_date OR f.km_at_removal IS NOT NULL AND f.km_at_fitment IS NOT NULL AND f.km_at_removal < f.km_at_fitment AS reversed,
            f.fit_date > CURRENT_DATE OR f.removal_date > CURRENT_DATE AS future_date,
            COALESCE(f.total_km, f.km_at_removal - f.km_at_fitment) > f.km_cap AS over_life_cap
           FROM f
        ), r AS (
         SELECT g.id,
            g.organisation_id,
            g.country,
            g.asset_no,
            g.site,
            g.brand,
            g.size,
            g.vehicle_type,
            g."position",
            g.serial_no,
            g.status,
            g.qty,
            g.fit_date,
            g.removal_date,
            g.km_at_fitment,
            g.km_at_removal,
            g.total_km,
            g.cost_per_tyre,
            g.strong,
            g.tyre_key,
            g.km,
            g.completed,
            g.active,
            g.fit_seq,
            g.is_overlap,
            g.job_card,
            g.created_at,
            g.km_cap,
            g.purchase_cost_status,
            g.era,
            g.is_duplicate,
            g.double_active_wheel,
            g.serial_active_two_vehicles,
            g.job_card_found,
            g.reversed,
            g.future_date,
            g.over_life_cap,
            array_remove(ARRAY[
                CASE
                    WHEN g.is_duplicate THEN 'duplicate_copy'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN g.reversed THEN 'reversed_dates_or_km'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN g.future_date THEN 'future_date'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN g.is_overlap THEN 'overlapping_fitment'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN g.double_active_wheel THEN 'two_active_on_wheel'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN g.serial_active_two_vehicles THEN 'serial_active_on_two_vehicles'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN g.over_life_cap THEN 'life_above_class_cap'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN NOT g.strong THEN 'serial_not_verified'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN NOT g.job_card_found THEN 'job_card_not_found'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN g.km_at_fitment = 1::numeric THEN 'fitment_km_placeholder'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN g.km_at_fitment IS NULL THEN 'fitment_km_missing'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN NOT g.active AND g.km_at_removal IS NULL THEN 'removal_km_missing'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN g.completed AND g.km IS NULL THEN 'life_not_measurable'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN g.purchase_cost_status = 'ESTIMATED'::text THEN 'price_estimated'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN g.purchase_cost_status = 'MISSING'::text THEN 'price_missing'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN g.purchase_cost_status = 'DISPUTED'::text THEN 'price_disputed'::text
                    ELSE NULL::text
                END], NULL::text) AS reasons
           FROM g
        )
 SELECT id,
    organisation_id,
    country,
    asset_no,
    site,
    brand,
    size,
    vehicle_type,
    "position",
    serial_no,
    status,
    qty,
    fit_date,
    removal_date,
    km_at_fitment,
    km_at_removal,
    total_km,
    km,
    cost_per_tyre,
    job_card,
    strong,
    tyre_key,
    fit_seq,
    active,
    completed,
    purchase_cost_status,
    era,
    is_duplicate,
    reversed,
    future_date,
    is_overlap,
    double_active_wheel,
    serial_active_two_vehicles,
    over_life_cap,
    job_card_found,
    reasons,
        CASE
            WHEN era = 'legacy'::text THEN 'LEGACY'::text
            WHEN era = 'undated'::text THEN 'UNDATED'::text
            WHEN is_duplicate THEN 'DUPLICATE'::text
            WHEN reversed OR future_date OR is_overlap OR double_active_wheel OR serial_active_two_vehicles OR COALESCE(over_life_cap, false) THEN 'CONFLICTING'::text
            WHEN NOT strong AND NOT job_card_found THEN 'MISSING_EVIDENCE'::text
            WHEN km_at_fitment = 1::numeric OR purchase_cost_status = 'ESTIMATED'::text THEN 'PROVISIONAL'::text
            WHEN NOT strong OR NOT job_card_found OR km_at_fitment IS NULL OR completed AND km IS NULL OR NOT active AND km_at_removal IS NULL OR (purchase_cost_status = ANY (ARRAY['MISSING'::text, 'DISPUTED'::text])) THEN 'PARTIALLY_VERIFIED'::text
            ELSE 'VERIFIED'::text
        END AS evidence_class
   FROM r;
